use crate::{canonical, hash_event, CaseEvent};
use serde::{Deserialize, Serialize};
use serde_json::{json, Value};
use sha2::{Digest, Sha256};
use std::{collections::{HashMap, HashSet}, fs::{self, OpenOptions}, io::Write, path::{Component, Path, PathBuf}};

#[derive(Clone, Serialize, Deserialize)]
#[serde(rename_all="camelCase")]
pub struct BundleFile { pub path:String, pub content:String, pub sha256:String }
#[derive(Clone, Serialize, Deserialize)]
#[serde(rename_all="camelCase")]
pub struct ProjectBundle { pub format:String, pub created_at:String, pub files:Vec<BundleFile>, pub sha256:String }
#[derive(Serialize)]
#[serde(rename_all="camelCase")]
pub struct BundlePreview { pub valid:bool, pub errors:Vec<String>, pub file_count:usize, pub case_count:usize, pub case_ids:Vec<String> }

fn sha(bytes:&[u8])->String { format!("{:x}",Sha256::digest(bytes)) }
fn safe(value:&str)->Result<PathBuf,String> { let p=Path::new(value); if p.as_os_str().is_empty()||p.is_absolute()||p.components().any(|c|!matches!(c,Component::Normal(_))){Err(format!("Unsafe path: {value}"))}else{Ok(p.to_path_buf())} }
fn file(path:&str,content:String)->BundleFile { BundleFile{path:path.into(),sha256:sha(content.as_bytes()),content} }
fn bundle_hash(b:&ProjectBundle)->Result<String,String>{let mut v=serde_json::to_value(b).map_err(|e|e.to_string())?;v["sha256"]=Value::String(String::new());Ok(sha(serde_json::to_string(&canonical(&v)).map_err(|e|e.to_string())?.as_bytes()))}
fn encode(format:&str,files:Vec<BundleFile>)->Result<String,String>{let mut b=ProjectBundle{format:format.into(),created_at:chrono::Utc::now().to_rfc3339(),files,sha256:String::new()};b.sha256=bundle_hash(&b)?;serde_json::to_string_pretty(&b).map_err(|e|e.to_string())}
fn decode(s:&str)->Result<ProjectBundle,String>{serde_json::from_str(s).map_err(|e|format!("Invalid bundle JSON: {e}"))}
fn validate(b:&ProjectBundle)->Result<BundlePreview,String>{let mut errors=Vec::new();if !b.format.ends_with("-bundle-v1"){errors.push("Unsupported bundle format".into())}if b.sha256!=bundle_hash(b)?{errors.push("Bundle SHA-256 mismatch".into())}let mut paths=HashSet::new();for f in &b.files{if safe(&f.path).is_err(){errors.push(format!("Unsafe path {}",f.path))}if !paths.insert(f.path.clone()){errors.push(format!("Duplicate path {}",f.path))}if sha(f.content.as_bytes())!=f.sha256{errors.push(format!("File hash mismatch {}",f.path))}}let mut cases:HashMap<String,Vec<CaseEvent>>=HashMap::new();if let Some(reg)=b.files.iter().find(|f|f.path=="REGISTER-PREVERJANJ.jsonl"){for(i,l)in reg.content.lines().enumerate(){if l.trim().is_empty(){continue}match serde_json::from_str::<Value>(l){Ok(row)=>if let Some(v)=row.get("case_event"){match serde_json::from_value::<CaseEvent>(v.clone()){Ok(e)=>cases.entry(e.case_id.clone()).or_default().push(e),Err(e)=>errors.push(format!("Bad event line {}: {e}",i+1))}},Err(e)=>errors.push(format!("Bad JSONL line {}: {e}",i+1))}}}for(id,events)in &cases{let mut prev=None;for(i,e)in events.iter().enumerate(){if e.sequence!=i as u64+1||e.previous_hash!=prev||e.hash!=hash_event(e){errors.push(format!("Broken event chain {id}"))}prev=Some(e.hash.clone())}}let mut ids=cases.keys().cloned().collect::<Vec<_>>();ids.sort();Ok(BundlePreview{valid:errors.is_empty(),errors,file_count:b.files.len(),case_count:cases.len(),case_ids:ids})}
pub fn preview_text(s:&str)->Result<BundlePreview,String>{validate(&decode(s)?)}
pub fn preview_file(p:&Path)->Result<BundlePreview,String>{preview_text(&fs::read_to_string(p).map_err(|e|e.to_string())?)}
pub fn export_project(root:&Path)->Result<String,String>{let m:Value=serde_json::from_slice(&fs::read(root.join("book.workbench.json")).map_err(|e|e.to_string())?).map_err(|e|e.to_string())?;let mut paths:Vec<String>=vec!["book.workbench.json".into(),"book.workbench.seal.json".into(),"REGISTER-PREVERJANJ.jsonl".into()];if let Some(items)=m["incomingTexts"].as_array(){for x in items{if let Some(p)=x["sourcePath"].as_str(){paths.push(p.into())}}}paths.sort();paths.dedup();let mut files=Vec::new();for p in paths{let rel=safe(&p)?;let full=root.join(&rel);if full.is_file(){let body=String::from_utf8(fs::read(full).map_err(|e|e.to_string())?).map_err(|e|e.to_string())?;files.push(file(&rel.to_string_lossy(),body))}}encode("atmavictu-project-bundle-v1",files)}
pub fn export_case(root:&Path,id:&str)->Result<String,String>{let source=fs::read_to_string(root.join("REGISTER-PREVERJANJ.jsonl")).map_err(|e|e.to_string())?;let mut rows=Vec::new();for l in source.lines().filter(|l|!l.trim().is_empty()){let row:Value=serde_json::from_str(l).map_err(|e|e.to_string())?;if row["case_event"]["caseId"].as_str()==Some(id){rows.push(row)}}if rows.is_empty(){return Err(format!("Case {id} not found"))}let m:Value=serde_json::from_slice(&fs::read(root.join("book.workbench.json")).map_err(|e|e.to_string())?).map_err(|e|e.to_string())?;let ids=rows.iter().filter_map(|r|r["case_event"]["payload"]["incomingTextId"].as_str()).collect::<HashSet<_>>();let mut reg=rows.iter().map(Value::to_string).collect::<Vec<_>>().join("\n");reg.push('\n');let mut files=vec![file("REGISTER-PREVERJANJ.jsonl",reg)];let mut incoming=Vec::new();if let Some(items)=m["incomingTexts"].as_array(){for e in items.iter().filter(|e|e["id"].as_str().is_some_and(|x|ids.contains(x))){let p=e["sourcePath"].as_str().ok_or("sourcePath missing")?;let rel=safe(p)?;let body=String::from_utf8(fs::read(root.join(&rel)).map_err(|e|e.to_string())?).map_err(|e|e.to_string())?;files.push(file(&rel.to_string_lossy(),body));incoming.push(e.clone())}}files.push(file("case-manifest-fragment.json",serde_json::to_string(&json!({"incomingTexts":incoming})).map_err(|e|e.to_string())?));encode("atmavictu-case-bundle-v1",files)}
pub fn restore_project(root:&Path,text:&str,overwrite:bool)->Result<BundlePreview,String>{let b=decode(text)?;let preview=validate(&b)?;if !preview.valid||b.format!="atmavictu-project-bundle-v1"{return Err(if preview.valid{"Expected project backup bundle".into()}else{preview.errors.join("; ")})}let paths=b.files.iter().map(|f|safe(&f.path)).collect::<Result<Vec<_>,_>>()?;let collisions=paths.iter().filter(|p|root.join(p).exists()).map(|p|p.display().to_string()).collect::<Vec<_>>();if !overwrite&&!collisions.is_empty(){return Err(format!("Restore target is not empty: {}",collisions.join(", ")))}let old=paths.iter().map(|p|(p.clone(),fs::read(root.join(p)).ok())).collect::<Vec<_>>();let mut written=Vec::new();for(f,p)in b.files.iter().zip(paths){let dest=root.join(&p);let result=(||->Result<(),String>{if let Some(parent)=dest.parent(){fs::create_dir_all(parent).map_err(|e|e.to_string())?}fs::write(&dest,f.content.as_bytes()).map_err(|e|e.to_string())})();if let Err(err)=result{for p in written{let _=fs::remove_file(root.join(p));}for(p,b)in old{if let Some(b)=b{let _=fs::write(root.join(p),b);}}return Err(err)}written.push(p)}Ok(preview)}
pub fn import_case(root:&Path,text:&str)->Result<BundlePreview,String>{let b=decode(text)?;let preview=validate(&b)?;if !preview.valid||b.format!="atmavictu-case-bundle-v1"{return Err(if preview.valid{"Expected case bundle".into()}else{preview.errors.join("; ")})}let reg=b.files.iter().find(|f|f.path=="REGISTER-PREVERJANJ.jsonl").ok_or("Register missing")?;let frag=b.files.iter().find(|f|f.path=="case-manifest-fragment.json").ok_or("Manifest fragment missing")?;let frag:Value=serde_json::from_str(&frag.content).map_err(|e|e.to_string())?;let rp=root.join("REGISTER-PREVERJANJ.jsonl");let mp=root.join("book.workbench.json");let sp=root.join("book.workbench.seal.json");let oldr=fs::read(&rp).ok();let oldm=fs::read(&mp).ok();let olds=fs::read(&sp).ok();let existing=oldr.as_ref().map(|b|String::from_utf8_lossy(b).into_owned()).unwrap_or_default();let mut known_cases=HashSet::new();for l in existing.lines(){if let Ok(v)=serde_json::from_str::<Value>(l){if let Some(id)=v["case_event"]["caseId"].as_str(){known_cases.insert(id.to_owned());}}}let rows=reg.content.lines().filter(|l|!l.trim().is_empty()).map(|l|serde_json::from_str::<Value>(l).map_err(|e|e.to_string())).collect::<Result<Vec<_>,_>>()?;for r in &rows{let id=r["case_event"]["caseId"].as_str().ok_or("Case id missing")?;if known_cases.contains(id){return Err(format!("Case {id} already exists"))}}let mut m:Value=match &oldm{Some(b)=>serde_json::from_slice(b).map_err(|e|e.to_string())?,None=>json!({"manifestVersion":"2","incomingTexts":[],"fragments":[],"insertions":[],"concepts":[]})};let entries=m["incomingTexts"].as_array_mut().ok_or("incomingTexts missing")?;let mut ids=entries.iter().filter_map(|e|e["id"].as_str().map(str::to_owned)).collect::<HashSet<_>>();let bypath=b.files.iter().map(|f|(f.path.as_str(),f)).collect::<HashMap<_,_>>();let mut writes=Vec::new();for mut e in frag["incomingTexts"].as_array().ok_or("sources missing")?.clone(){let id=e["id"].as_str().ok_or("source id missing")?.to_owned();let p=e["sourcePath"].as_str().ok_or("sourcePath missing")?.to_owned();if !ids.insert(id.clone()){return Err(format!("Source ID collision: {id}"))}let rel=safe(&p)?;let f=bypath.get(p.as_str()).ok_or("source bytes missing")?;if root.join(&rel).exists(){return Err(format!("Source path collision: {p}"))}e["status"]=Value::String("new".into());writes.push((rel,f.content.clone()));entries.push(e)}let compact=serde_json::to_string(&m).map_err(|e|e.to_string())?;let pretty=format!("{}\n",serde_json::to_string_pretty(&m).map_err(|e|e.to_string())?);let seal=json!({"manifestPath":mp.to_string_lossy(),"manifestSha256":sha(compact.as_bytes()),"receipts":{"manifest":true,"seal":true,"cli":false,"ci":false},"clock":{"sealedAt":chrono::Utc::now().to_rfc3339_opts(chrono::SecondsFormat::Millis,true),"receivedAt":null,"ci":false,"cli":false}});let mut written=Vec::new();let tx=(||->Result<(),String>{for(rel,body)in &writes{let d=root.join(rel);if let Some(parent)=d.parent(){fs::create_dir_all(parent).map_err(|e|e.to_string())?}fs::write(&d,body).map_err(|e|e.to_string())?;written.push(rel.clone())}fs::write(&mp,pretty).map_err(|e|e.to_string())?;fs::write(&sp,format!("{}\n",serde_json::to_string_pretty(&seal).map_err(|e|e.to_string())?)).map_err(|e|e.to_string())?;let mut out=OpenOptions::new().create(true).append(true).open(&rp).map_err(|e|e.to_string())?;for r in &rows{writeln!(out,"{r}").map_err(|e|e.to_string())?}Ok(())})();if let Err(err)=tx{for rel in written{let _=fs::remove_file(root.join(rel));}restore_bytes(&rp,oldr);restore_bytes(&mp,oldm);restore_bytes(&sp,olds);return Err(err)}Ok(preview)}
fn restore_bytes(p:&Path,b:Option<Vec<u8>>){match b{Some(b)=>{let _=fs::write(p,b);},None=>{let _=fs::remove_file(p);}}}
